$canRegister=$isAdmin||$isGvcn; $canApprove=$isAdmin||can_edit_perm('nt.ravao');
$sub=$_GET['view']??'register'; if(!in_array($sub,['register','history','check','settings'],true))$sub='register';
if($sub==='register'&&!$canRegister)$sub='history'; if($sub==='settings'&&!$canApprove)$sub='history';
