function nt_exit_drive_folder():array{
 $s=cds_drive_settings(); if(!isset($s['types']['ktx_exit_applications'])){$s['types']['ktx_exit_applications']=['label'=>'Đơn xin ra vào KTX','folder_id'=>'','prefix'=>'Don-xin-ra-vao-KTX'];}
 if(trim((string)$s['types']['ktx_exit_applications']['folder_id'])===''){
  $token=cds_drive_token($s); if(empty($token['ok']))return ['ok'=>false,'message'=>$token['message']??'Chưa kết nối Google Drive.'];
  $meta=json_encode(['name'=>'Đơn xin ra vào KTX','mimeType'=>'application/vnd.google-apps.folder'],JSON_UNESCAPED_UNICODE);
  $r=cds_drive_http('https://www.googleapis.com/drive/v3/files?fields=id,name','POST',['Authorization: Bearer '.$token['token'],'Content-Type: application/json; charset=UTF-8'],$meta); $j=json_decode($r['body'],true);
  if(!$r['ok']||empty($j['id']))return ['ok'=>false,'message'=>$j['error']['message']??'Không tạo được thư mục Đơn xin ra vào KTX.'];
  $s['types']['ktx_exit_applications']['folder_id']=$j['id']; cds_drive_save_settings($s);
 }
 return ['ok'=>true,'id'=>$s['types']['ktx_exit_applications']['folder_id']];
}
function nt_exit_upload(string $field):string{
 if(empty($_FILES[$field])||($_FILES[$field]['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return '';
 $f=$_FILES[$field]; if(($f['error']??1)!==UPLOAD_ERR_OK)throw new RuntimeException('Không nhận được file đơn xin.');
 $ext=strtolower(pathinfo((string)$f['name'],PATHINFO_EXTENSION)); if(!in_array($ext,['pdf','jpg','jpeg','png','webp'],true))throw new RuntimeException('Đơn xin chỉ nhận PDF hoặc ảnh JPG/PNG/WEBP.');
 if((int)$f['size']>15*1024*1024)throw new RuntimeException('File đơn xin tối đa 15 MB.');
 $folder=nt_exit_drive_folder(); if(empty($folder['ok']))throw new RuntimeException($folder['message']);
 $s=cds_drive_settings(); $s['types']['ktx_exit_applications']['folder_id']=$folder['id']; cds_drive_save_settings($s);
 $bytes=file_get_contents($f['tmp_name']); $mime=mime_content_type($f['tmp_name'])?:'application/octet-stream';
 $r=cds_drive_upload_bytes($bytes,(string)$f['name'],$mime,'ktx_exit_applications',['title'=>'Đơn xin ra vào KTX']); if(empty($r['ok']))throw new RuntimeException($r['message']??'Không tải được đơn lên Google Drive.');
 return 'gdrive:'.$r['id'];
}
function nt_exit_find(string $id):?array{foreach(noitru_exits_all() as $r)if(($r['id']??'')===$id)return $r;return null;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  $a=$_POST['action']??'';
  if($a==='save_settings'&&$canApprove){$settings=['registration_open'=>!empty($_POST['registration_open']),'open_from'=>$_POST['open_from']??'00:00','open_to'=>$_POST['open_to']??'23:59','allow_application_upload'=>!empty($_POST['allow_application_upload']),'application_required'=>!empty($_POST['application_required']),'allow_search'=>!empty($_POST['allow_search'])];save_json($settingsFile,$settings);flash('Đã lưu cài đặt ra/vào KTX.');}
  elseif($a==='save_exit'&&$canRegister){
   $id=trim($_POST['id']??''); $old=$id?nt_exit_find($id):null; if($old&&($old['status']??'pending')!=='pending')throw new RuntimeException('Phiếu đã duyệt/từ chối nên không thể sửa.');
   if(!$isAdmin&&!$settings['registration_open'])throw new RuntimeException('Đăng ký ra/vào KTX đang khóa.');
   $sid=trim($_POST['student_id']??''); $map=[]; foreach(noitru_boarders_live() as $s)$map[$s['id']]=$s; $st=$map[$sid]??null; if(!$st||!can_class($st['class_name']??''))throw new RuntimeException('Học sinh không thuộc phạm vi lớp được giao.');
   $from=trim($_POST['from_date']??'');$to=trim($_POST['to_date']??'');$reason=trim($_POST['reason']??''); if($sid===''||$from===''||$to===''||$reason==='')throw new RuntimeException('Học sinh, thời gian và lý do là bắt buộc.'); if($to<$from)throw new RuntimeException('Thời gian trở vào phải sau thời gian ra.');
   $app=nt_exit_upload('application'); if($app===''&&$old)$app=$old['application']??''; if($settings['application_required']&&$app==='')throw new RuntimeException('Cài đặt yêu cầu phải có đơn xin đính kèm.');
   noitru_exit_save(['id'=>$id,'student_id'=>$sid,'student_name'=>$st['name']??'','class_name'=>$st['class_name']??'','from_date'=>$from,'to_date'=>$to,'reason'=>$reason,'pickup_name'=>trim($_POST['pickup_name']??''),'pickup_phone'=>trim($_POST['pickup_phone']??''),'application'=>$app,'status'=>$old['status']??'pending','created_by'=>$old['created_by']??($user['name']??''),'updated_by'=>$user['name']??'']); flash($id?'Đã cập nhật đơn.':'Đã gửi đăng ký ra/vào KTX.');
  } elseif($a==='status'&&$canApprove){$r=nt_exit_find(trim($_POST['id']??''));if($r){$r['status']=in_array($_POST['status']??'', ['approved','rejected','pending'],true)?$_POST['status']:'pending';$r['approved_by']=$user['name']??'';$r['approved_at']=noitru_now();noitru_exit_save($r);flash('Đã cập nhật trạng thái đơn.');}}
  elseif($a==='confirm_gate'){$r=nt_exit_find(trim($_POST['id']??''));if(!$r||($r['status']??'')!=='approved')throw new RuntimeException('Học sinh chưa có đơn được duyệt.');$mode=$_POST['mode']??'out';$key=$mode==='in'?'actual_in_at':'actual_out_at';$r[$key]=noitru_now();$r[$mode==='in'?'checked_in_by':'checked_out_by']=$user['name']??'';noitru_exit_save($r);flash($mode==='in'?'Đã xác nhận học sinh trở vào KTX.':'Đã xác nhận học sinh ra khỏi KTX.');}
 }catch(Throwable $e){flash($e->getMessage(),'danger');}
 header('Location: '.BASE_URL.'noitru_exit_manager.php?view='.urlencode($sub));exit;
}
$boarders=array_values(array_filter(noitru_boarders_live(),fn($s)=>can_class($s['class_name']??'')));$classes=array_values(array_unique(array_filter(array_column(noitru_boarders_live(),'class_name'))));usort($classes,'csdl_compare_class_names');
$rows=noitru_exits_all();$today=date('Y-m-d');$period=$_GET['period']??'day';$from=$_GET['from']??$today;$to=$_GET['to']??$today;if($period==='week'){$from=date('Y-m-d',strtotime('monday this week'));$to=date('Y-m-d',strtotime('sunday this week'));}elseif($period==='month'){$from=date('Y-m-01');$to=date('Y-m-t');}$class=trim($_GET['class']??'');$q=trim($_GET['q']??'');
$history=array_values(array_filter($rows,function($r)use($from,$to,$class,$q){if(($r['status']??'')!=='approved')return false;$d=substr($r['from_date']??'',0,10);if($d<$from||$d>$to)return false;if($class!==''&&($r['class_name']??'')!==$class)return false;if($q!==''&&stripos(($r['student_name']??'').' '.($r['reason']??''),$q)===false)return false;return true;}));usort($history,fn($a,$b)=>strcmp($a['from_date']??'',$b['from_date']??''));
if($sub==='history'&&($_GET['export']??'')==='excel'){header('Content-Type: application/vnd.ms-excel; charset=UTF-8');header('Content-Disposition: attachment; filename="danh-sach-ra-vao-KTX-'.$from.'-'.$to.'.xls"');echo "\xEF\xBB\xBF";echo '<table border="1"><tr><th colspan="10">'.htmlspecialchars(SCHOOL_NAME).'</th></tr><tr><th colspan="10">DANH SÁCH HỌC SINH RA VÀO KTX TỪ '.date('d/m/Y',strtotime($from)).' ĐẾN '.date('d/m/Y',strtotime($to)).'</th></tr><tr><th>STT</th><th>Học sinh</th><th>Lớp</th><th>Thời gian đăng ký ra</th><th>Thời gian đăng ký vào</th><th>Ra thực tế</th><th>Vào thực tế</th><th>Lý do</th><th>Người đón</th><th>SĐT</th></tr>';foreach($history as $i=>$r)echo '<tr><td>'.($i+1).'</td><td>'.htmlspecialchars($r['student_name']??'').'</td><td>'.htmlspecialchars($r['class_name']??'').'</td><td>'.htmlspecialchars($r['from_date']??'').'</td><td>'.htmlspecialchars($r['to_date']??'').'</td><td>'.htmlspecialchars($r['actual_out_at']??'').'</td><td>'.htmlspecialchars($r['actual_in_at']??'').'</td><td>'.htmlspecialchars($r['reason']??'').'</td><td>'.htmlspecialchars($r['pickup_name']??'').'</td><td>'.htmlspecialchars($r['pickup_phone']??'').'</td></tr>';echo '</table>';exit;}
